#include "runtime/interpreter.hpp"
#include <chrono>
#include <filesystem>
#include <fstream>
#include <iostream>
#include <string>
int main(){using namespace penta;unsigned checks=0,failures=0;runtime::ExecutionOptions options;options.dataDirectory=std::filesystem::temp_directory_path()/("penta-transient-fem-"+std::to_string(std::chrono::steady_clock::now().time_since_epoch().count()));options.odeCacheDirectory=options.dataDirectory/"cache/odes";options.maxOperations=100000000;std::filesystem::create_directories(options.dataDirectory);auto run=[&](const std::string& source){++checks;const auto result=runtime::execute(source,{},options);if(!result.ok()){++failures;for(const auto& d:result.analysis.diagnostics)std::cerr<<d.code<<" @"<<d.span.offset<<": "<<d.message<<'\n';for(const auto& d:result.runtimeDiagnostics)std::cerr<<d.code<<" @"<<d.span.offset<<": "<<d.message<<'\n';}};
run("native function [real x,real y] plane(real u,real v){return u,v;}native function real reaction(real u,real t,real x,real y,real rate){return rate*u;}record mesh=paramesh(plane,[0,1],[0,1]);record a=femtime(reaction,mesh,options(parameters=options(rate=1.0),initial=1.0,order=3,adaptive=0,t1=.02,time_step=.01,sample_step=.01));record b=femtime(reaction,mesh,options(parameters=options(rate=2.0),initial=1.0,order=3,adaptive=0,t1=.02,time_step=.01,sample_step=.01));assert(a.converged&&b.converged);assert(a.cache_keys==b.cache_keys&&b.cache_hit);matrix u=femtimecoeff(a,0);assert(abs(u(end,1)-(1.01)^(-2))<1e-9);record first=femtimeslice(a,1);record last=femtimeslice(a,length(a.t));assert(norm(first.dof_values-1,\"fro\")<1e-10);assert(norm(last.dof_values-a.field.dof_values,\"fro\")<1e-10);assert(norm(last.visualization_values-a.field.visualization_values,\"fro\")<1e-10);figure(1);femsystemplot(first);femsystemplot(last);");
run("native function [real x,real y] plane(real u,real v){return u,v;}native function real reaction(real u,real t,real x,real y){return 0.0;}native function real initial(real t,real x,real y){return x*x;}native function real boundary(real t,real x,real y){return x*x+t;}native function real forcing(real t,real x,real y){return -1-4*x-2*t;}native function real diffusion(real t,real x,real y){return 1+x+t;}record mesh=paramesh(plane,[0,1],[0,1]);record a=femtime(reaction,mesh,options(forcing=forcing,initial=initial,diffusion=diffusion,boundary=\"dirichlet\",boundary_value=boundary,order=2,adaptive=0,t1=.02,time_step=.01,sample_step=.01));assert(a.converged);matrix expected=a.field.dof_coordinates(:,1).^2+.02;assert(norm(a.field.dof_values-expected,\"fro\")<1e-8);");
run("algebra H=builtin_algebra(\"quaternion\");native function [real x,real y] plane(real u,real v){return u,v;}native function element<H> reaction(element<H> q,real t,real x,real y){return q;}record mesh=paramesh(plane,[0,1],[0,1]);record a=femtime(reaction,mesh,options(initial=1+.2*H.i+.3*H.j,order=2,adaptive=0,t1=.01,time_step=.01,sample_step=.01));assert(a.components==4);assert(a.algebra_hash==algebra_info(H).hash);matrix scalar_part=femtimecoeff(a,0);matrix component=femtimecoeff(a,1);assert(norm(component-.2*scalar_part,\"fro\")<1e-10);assert(norm(femtimecoeff(a,3),\"fro\")<1e-10);");
#ifdef PENTA_SOURCE_DIR
for(const auto* name:{"transient-stiff-cubic.p","transient-curved-surface.p"}){std::ifstream input(std::filesystem::path(PENTA_SOURCE_DIR)/"examples/high-order-finite-elements"/name);run(std::string((std::istreambuf_iterator<char>(input)),{}));}
#endif
std::error_code ignored;std::filesystem::remove_all(options.dataDirectory,ignored);std::cout<<checks<<" transient FEM language checks, "<<failures<<" failures\n";return failures?1:0;}
